# Generates assets/js/leon46-config.js from .env.local for local development.
# The generated file is git-ignored, so keys are never committed.
#
#   ruby scripts/leon46-env.rb
#
# Only PUBLIC_* values are written (they end up in the browser anyway).

root = File.expand_path("..", __dir__)
env_path = File.join(root, ".env.local")
out_path = File.join(root, "assets", "js", "leon46-config.js")

abort "Missing .env.local (copy .env.example and fill it in)." unless File.exist?(env_path)

env = {}
File.readlines(env_path, chomp: true, encoding: "UTF-8").each do |line|
  line = line.strip
  next if line.empty? || line.start_with?("#")
  key, value = line.split("=", 2)
  next unless key && value
  env[key.strip] = value.strip.delete_prefix('"').delete_suffix('"').delete_prefix("'").delete_suffix("'")
end

url = env["PUBLIC_SUPABASE_URL"].to_s
key = env["PUBLIC_SUPABASE_ANON_KEY"].to_s
abort "PUBLIC_SUPABASE_URL and PUBLIC_SUPABASE_ANON_KEY must be set in .env.local." if url.empty? || key.empty?

require "json"
Dir.mkdir(File.dirname(out_path)) unless Dir.exist?(File.dirname(out_path))
File.write(out_path, <<~JS)
  // Generated by scripts/leon46-env.rb from .env.local. Do not commit.
  window.LEON46_CONFIG = #{JSON.generate({ supabaseUrl: url, supabaseAnonKey: key })};
JS
puts "Wrote #{out_path}"
